'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={recipe:'标准配方',sop:'操作流程',rule:'规章制度',service_script:'服务话术',complaint_card:'客诉升级卡',service_scenario:'服务培训场景'};
const states={draft:'草稿',review:'待审核',published:'已发布／待生效',retired:'已停用'};
let scopeOptions=[],accountUsers=[];
const stationName=s=>scopeOptions.find(o=>o.kind==='station'&&o.code===s)?.label||({main:'主吧台',terrace:'露台吧台'}[s]||s);
let user,csrf='',station='',page='home',knowledge=[],revisions=[],trainingTasks=[],trainingDetail,modules=[],queryResult;
let busy=false;
let simulatedEnvironment=false;
let activeStore='',storeContexts=[];
const date=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未设置';
function toast(message){$('#notice').textContent=message;$('#notice').classList.add('visible');setTimeout(()=>$('#notice').classList.remove('visible'),4500)}
async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',signal:controller.signal,credentials:'same-origin',headers:{...(body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf}),...(activeStore?{'X-BarOS-Store':activeStore}:{})},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{throw Error('服务暂不可用，请稍后重试')}if(!r.ok){if(r.status===401&&path!=='/login'){user=null;csrf='';closeModal();renderLogin()}throw Error(typeof data.detail==='string'?data.detail:'填写内容有误，请检查必填项、日期与格式。')}return data}catch(e){if(e.name==='AbortError')throw Error(body===undefined?'读取超时，请重试':'请求超时，结果尚未确认。请先刷新查看记录，避免重复提交。');if(e instanceof TypeError)throw Error('网络连接失败，请检查网络后重试');throw e}finally{clearTimeout(timer)}}
function showModal(html){$('#modal-body').innerHTML=(simulatedEnvironment?'<p class="demo-modal-label">SIMULATED DATA / 模拟数据 · 独立演示环境</p>':'')+html;$('#modal').showModal()}
function closeModal(){$('#modal').close();$('#modal-body').innerHTML=''}
function renderLogin(){ activeStore='';storeContexts=[];$('#app').innerHTML='<div class="login"><section class="login-story"><div class="logo">bar<span>OS</span></div><h1>每一班，都有标准可循。</h1><p>查配方、学流程、做好交接。<br>把门店的经验，变成每个人都能找到的答案。</p></section><section class="login-form"><form id="login"><h2>登录工作台</h2><p class="muted">使用主管为你开通的员工账号</p><label for="username">账号</label><input id="username" name="username" autocomplete="username" required><label for="password">密码</label><input id="password" name="password" type="password" autocomplete="current-password" required><p id="login-error" class="error" role="alert"></p><button class="primary">登录</button><p class="small muted">首次使用请先运行初始化命令，设置账号密码。</p></form></section></div>' }
function shell(){const manage=user.role!=='staff';const nav=[['home','工作首页'],['knowledge','知识手册'],['training','Academy 培训学院'],['evidence','我的技能证据'],['flow','Flow 工作流'],['service','Service 服务智能'],['inventory','Inventory 库存智能'],['agents','Agents 新品准备'],['requests','我的求助']];if(manage||user.hq_owner)nav.push(['hq','HQ 连锁总部']);if(manage)nav.push(['divider',''],['command','Command 店长中心'],['insight','Insight 经营分析'],['manage','知识管理'],['memory','知识维护'],['proposals','知识提案'],['team','培训管理'],['feedback','反馈中心'],['stats','使用看板']);if(user.role==='admin')nav.push(['accounts','账号管理'],['settings','岗位与吧台']);nav.push(['password','修改密码']);$('#app').innerHTML='<div class="shell"><aside class="rail"><div class="logo">bar<span>OS</span></div><small>员工知识与培训工作台</small><nav class="nav">'+nav.map(([id,label])=>id==='divider'?'<div class="divider"></div>':'<button data-page="'+id+'" class="'+(id===page?'active':'')+'">'+label+'</button>').join('')+'</nav><div class="profile"><strong>'+esc(user.name)+'</strong><small>'+esc(user.job)+' / '+esc({staff:'员工',manager:'主管',admin:'管理员'}[user.role])+'</small><button data-action="logout">退出登录</button></div></aside><main class="main"><header class="topbar"><div class="station"><span class="small muted">当前吧台</span><select id="station" aria-label="当前吧台">'+user.stations.map(s=>'<option value="'+esc(s)+'" '+(s===station?'selected':'')+'>'+esc(stationName(s))+'</option>').join('')+'</select></div><div id="store-context">'+(activeStore?'<button data-org-home="1">返回本店</button>':'<span class="live">仅展示已授权有效标准</span>')+'</div><button data-action="logout" class="small">退出</button></header><div class="content" id="content"></div></main></div>'}
function heading(title,description,action=''){return '<div class="pagehead"><div><h1>'+title+'</h1><p class="muted">'+description+'</p></div>'+action+'</div>'}
function knowledgeCard(k){return '<button class="knowledge-card" data-open="'+k.id+'"><span class="tag '+k.kind+'">'+kinds[k.kind]+'</span><h3>'+esc(k.title)+'</h3><p>'+esc(k.content.summary)+'</p><div class="meta"><span>v'+k.version+'</span><span>'+esc(k.stations.map(stationName).join(' / '))+'</span></div></button>'}
function cards(items){return items.length?'<div class="grid">'+items.map(knowledgeCard).join('')+'</div>':'<div class="empty">暂无已授权的有效资料。请联系主管添加并发布门店标准。</div>'}
const trainingStates={stale:'需更新课程或重学',completed:'培训完成',practical:'待主管实操',learning:'待学习与测验'};
function trainingRow(t){const status=t.status||(t.stale?'stale':t.practical_at?'completed':t.best_score!==null&&t.best_score>=t.pass_score?'practical':'learning');return '<div class="list-row"><div><h3>'+esc(t.title)+' <span class="small muted">v'+(t.version||1)+'</span></h3><p class="muted small">'+trainingStates[status]+' · '+(t.best_score!==null?'最高 '+t.best_score+' 分':'尚未测验')+'</p><p class="small">'+esc(t.stale_reason||'')+(t.due_at?' · 截止 '+date(t.due_at):'')+(t.overdue?' <span class="tag attention">已逾期</span>':'')+'</p></div><button data-training="'+t.id+'" '+(t.stale?'disabled':'')+'>查看任务</button></div>'}

async function render(){if(user.must_change_password){closeModal();$('#app').innerHTML='<main class="content"><div class="panel"><h1>设置你的新密码</h1><p>为保护账号，请先更改主管提供的初始密码，再进入工作台。</p>'+passwordForm()+'</div></main>';return}shell();let content=$('#content');content.innerHTML='<p class="muted">正在读取…</p>';try{scopeOptions=await api('/config');shell();content=$('#content');if(typeof renderStoreContext==='function')await renderStoreContext();if(['home','knowledge'].includes(page)){knowledge=await api('/knowledge?station='+encodeURIComponent(station));if(page==='home'){const tasks=await api('/training');content.innerHTML='<section class="search-area"><h1>今天需要查什么？</h1><p>标准配方、操作流程与服务规范，查到当前有效版本。</p><form id="ask" class="search"><input name="question" aria-label="你的问题" placeholder="例如：金汤力的标准配方是什么？" minlength="2" maxlength="500" required><button class="primary">查询标准</button></form><div class="chips">'+knowledge.slice(0,4).map(k=>'<button data-ask="'+esc(k.title)+'">'+esc(k.title)+'</button>').join('')+'</div></section><div id="answer"></div><div class="section-title"><h2>常用标准</h2><span class="muted small">'+knowledge.length+' 项有效知识</span></div>'+cards(knowledge.slice(0,6))+'<div class="section-title"><h2>我的培训</h2></div><div class="panel">'+(tasks.length?tasks.map(trainingRow).join(''):'<p class="muted">暂无培训任务，主管分配后会显示在这里。</p>')+'</div>'}else{content.innerHTML=heading('知识手册','配方和流程以当前吧台的有效版本为准。')+'<label for="filter">搜索标题或别名</label><input id="filter" placeholder="输入名称或别名"><div class="tabs"><button data-filter-kind="all" class="active">全部</button><button data-filter-kind="recipe">标准配方</button><button data-filter-kind="sop">操作流程</button><button data-filter-kind="rule">规章制度</button><button data-filter-kind="service_script">服务话术</button><button data-filter-kind="complaint_card">客诉升级卡</button><button data-filter-kind="service_scenario">培训场景</button></div><div id="knowledge-list" class="panel">'+cards(knowledge)+'</div>'}}
else if(page==='hq'){await renderHQ(content)}
else if(page==='agents'){await renderAgents(content)}
else if(page==='service'){await renderService(content)}
else if(page==='inventory'){await renderInventory(content)}
else if(page==='insight'){await renderInsight(content)}
else if(page==='command'){await renderCommand(content)}
else if(page==='flow'){await renderFlow(content)}
else if(page==='evidence'){await renderEvidence(content)}
else if(page==='memory'){await renderMemory(content)}
else if(page==='proposals'){await renderProposals(content)}
else if(page==='requests'){await renderRequests(content)}
else if(page==='training'){trainingTasks=await api('/training');content.innerHTML=heading('我的培训','完成理论测验后，由主管进行实际操作验收。')+'<div class="panel">'+(trainingTasks.length?trainingTasks.map(trainingRow).join(''):'<div class="empty">暂未分配学习任务。</div>')+'</div>'}
else if(page==='manage'){revisions=await api('/manage/revisions');content.innerHTML=heading('知识管理','已发布内容保留历史；修改标准请创建新版本。','<button class="primary" data-action="draft">新增知识</button>')+'<div class="panel">'+(revisions.length?revisions.map(r=>'<div class="list-row"><div><h3>'+esc(r.title)+' <span class="small muted">v'+r.version+'</span></h3><span class="tag">'+states[r.state]+'</span><p class="small muted">生效：'+date(r.effective_at)+'</p></div><div class="actions"><button data-review="'+r.id+'">查看</button><button data-diff="'+r.id+'">版本差异</button>'+(r.state==='draft'?'<button data-edit-draft="'+r.id+'">编辑草稿</button><button data-submit="'+r.id+'">提交审核</button>':'')+(r.state==='review'?'<button class="primary" data-publish="'+r.id+'">审核发布</button>':'')+(r.state==='published'?'<button data-new-version="'+r.id+'">新版本</button><button data-retire="'+r.id+'">停用</button>':'')+'</div></div>').join(''):'<div class="empty">从一份已确认的配方或 SOP 开始。</div>')+'</div>'}
else if(page==='feedback'){const items=await api('/manage/feedback');content.innerHTML=heading('反馈中心','反馈关联原始提问和知识版本；处理反馈不会更改正式资料。')+'<div class="panel">'+(items.length?items.map(f=>'<div class="list-row"><div><h3>'+esc(f.question)+'</h3><span class="tag">'+({helpful:'有帮助',missing:'找不到答案',error:'内容可能错误'}[f.kind])+' / '+(f.state==='open'?'待处理':'已处理')+'</span><p class="note">'+esc(f.description)+'</p><p class="muted small">引用版本编号：'+esc(f.revision_ids)+'　'+date(f.created_at)+'</p>'+(f.resolution?'<p>处理记录：'+esc(f.resolution)+'</p>':'')+'</div>'+(f.state==='open'?'<div class="actions"><button data-resolve="'+f.id+'">处理反馈</button>'+(f.kind!=='helpful'?'<button data-propose-feedback="'+f.id+'">转为知识提案</button>':'')+'</div>':'')+'</div>').join(''):'<div class="empty">暂无反馈。</div>')+'</div>'}
else if(page==='team'){await renderAcademy(content)}
else if(page==='stats'){const s=await api('/manage/stats');content.innerHTML=heading('使用看板','最近 7 天 · 真实系统记录')+'<div class="metrics">'+[['使用人数',s.users],['查询次数',s.queries],['未找到标准',s.unresolved],['待审核知识',s.pending]].map(([label,n])=>'<div class="metric"><span class="muted small">'+label+'</span><strong>'+n+'</strong></div>').join('')+'</div><div class="panel"><h2>高频问题</h2>'+s.frequent.map(f=>'<div class="list-row"><span>'+esc(f.question)+'</span><strong>'+f.count+' 次</strong></div>').join('')+(s.frequent.length?'':'<p class="muted">暂无查询记录。</p>')+'</div><p class="muted small">'+esc(s.definition)+'<br>北京时间 '+date(s.start)+' 至 '+date(s.end)+'<br>待处理问题反馈：'+s.open_feedback+' 条</p>'}
else if(page==='password'){content.innerHTML=heading('修改密码','修改后所有设备需要重新登录。')+'<div class="panel">'+passwordForm()+'</div>'}
else if(page==='settings'){content.innerHTML=heading('岗位与吧台','标识用于关联已有资料，显示名称可调整。新增吧台后请在账号管理中授权。')+'<div class="panel"><h2>新增或调整显示名称</h2><form id="scope-form"><div class="field-grid"><div><label>类型</label><select name="kind"><option value="job">岗位</option><option value="station">吧台</option></select></div>'+field('内部标识（英文、数字、下划线）','code')+field('显示名称','label')+'</div><div class="actions"><button class="primary">保存配置</button></div></form></div><div class="panel">'+scopeOptions.map(o=>'<div class="list-row"><span>'+esc(o.label)+'</span><span class="muted small">'+(o.kind==='job'?'岗位':'吧台')+' / '+esc(o.code)+'</span></div>').join('')+'</div>'}
else if(page==='accounts'){accountUsers=await api('/manage/users');content.innerHTML=heading('账号管理','修改岗位、吧台或重置密码后，员工需要重新登录。','<button class="primary" data-action="account">新增账号</button>')+'<div class="panel">'+accountUsers.map(u=>'<div class="list-row"><div><h3>'+esc(u.name)+'</h3><p class="muted small">'+esc(u.username)+' / '+esc(u.role)+' / '+esc(u.job)+' / '+esc(u.stations.map(stationName).join('、'))+(u.must_change_password?' / 首次登录需改密':'')+'</p></div>'+(u.id!==user.id?'<div class="actions"><button data-edit-user="'+u.id+'">岗位与权限</button><button data-reset-password="'+u.id+'">重置密码</button><button data-deactivate="'+u.id+'">停用</button></div>':'')+'</div>').join('')+'</div>'}
}catch(e){if(!user)return;content.innerHTML='<div class="empty">'+esc(e.message)+'<div class="actions"><button data-action="retry">重新加载</button></div></div>'}}
function cardDetail(k){const c=k.content;return '<span class="tag '+k.kind+'">'+kinds[k.kind]+'</span><h2>'+esc(k.title)+'</h2><p>'+esc(c.summary)+'</p>'+(c.ingredients.length?'<table class="recipe-table"><thead><tr><th>原料</th><th>标准用量</th></tr></thead><tbody>'+c.ingredients.map(i=>'<tr><td>'+esc(i.name)+'</td><td>'+esc(i.amount)+' '+esc(i.unit)+'</td></tr>').join('')+'</tbody></table><p>技法：'+esc(c.technique)+'　杯型：'+esc(c.glass)+'<br>装饰：'+esc(c.garnish)+'</p><p class="warning">过敏原：'+esc(c.allergens.join('、')||'未填写，请向主管确认；不代表无过敏原。')+'</p>':'')+'<ol class="steps">'+c.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol>'+(c.service?serviceBody(c.service):'')+'<div class="source">来源：'+esc(k.source)+'<br>v'+k.version+' · 生效：'+date(k.effective_at)+'<br>适用岗位：'+esc(k.jobs.join('、'))+'　吧台：'+esc(k.stations.map(stationName).join('、'))+'</div>'}
async function ask(question){queryResult=null;$('#answer').innerHTML='<p class="muted" role="status">正在核对当前有效标准…</p>';queryResult=await api('/ask',{question,station});$('#answer').innerHTML='<div class="panel"><h2>'+esc(question)+'</h2><p>'+esc(queryResult.message)+'</p>'+answerEvidence(queryResult)+queryResult.sources.map(cardDetail).join('<hr>')+'<div class="actions">'+(queryResult.resolved?'<button data-feedback="helpful">有帮助</button>':'')+'<button data-feedback="missing">找不到答案</button><button data-feedback="error">内容可能错误</button><button data-escalate="'+queryResult.query_id+'">请主管确认</button></div></div>';$('#answer').scrollIntoView({behavior:'auto',block:'start'})}
function field(label,name,value='',type='text',required=true){return '<div><label for="f-'+name+'">'+label+'</label><input id="f-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(required?'required':'')+'></div>'}
function area(label,name,value=''){return '<div class="wide"><label for="f-'+name+'">'+label+'</label><textarea id="f-'+name+'" name="'+name+'" required>'+esc(value)+'</textarea></div>'}
function draftForm(existing,editing=false,proposalId=''){if(existing&&['service_script','complaint_card','service_scenario'].includes(existing.kind))return serviceForm(existing,editing,proposalId);const k=existing||{},c=k.content||{};showModal('<h2>'+(editing?'编辑草稿':existing?'创建新版本':'新增知识')+'</h2><form id="draft-form" data-proposal="'+proposalId+'" data-edit="'+(editing?k.revision_id:'')+'" data-edit-version="'+(k.edit_version||1)+'" data-document="'+(k.id||'')+'"><div class="field-grid">'+field('知识标题','title',k.title)+ '<div><label>知识类型</label><select name="kind">'+Object.entries(kinds).filter(([v])=>!['service_script','complaint_card','service_scenario'].includes(v)).map(([v,l])=>'<option value="'+v+'" '+(k.kind===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div>'+field('适用岗位（逗号分隔）','jobs',(k.jobs||[user.job]).join(','))+field('适用吧台（逗号分隔）','stations',(k.stations||[station]).join(','))+field('别名（逗号分隔，可空）','aliases',(k.aliases||[]).join(','),'text',false)+field('资料来源／负责人确认记录','source',k.source)+field('变更原因（提案草稿必填）','change_reason',k.change_reason||'','text',Boolean(proposalId))+area('简短说明','summary',c.summary)+area('操作步骤（每行一步）','steps',(c.steps||[]).join('\n'))+area('原料（每行：名称 | 数量 | 单位；非配方填“无”）','ingredients',(c.ingredients||[]).map(i=>i.name+' | '+i.amount+' | '+i.unit).join('\n')||'无')+field('技法（非配方可空）','technique',c.technique,'text',false)+field('杯型（非配方可空）','glass',c.glass,'text',false)+field('装饰（可空）','garnish',c.garnish,'text',false)+field('过敏原（逗号分隔，可空）','allergens',(c.allergens||[]).join(','),'text',false)+'</div><label><input name="risk" type="checkbox" '+(k.risk?'checked':'')+'> 涉及过敏、安全等高风险标准</label><p class="small muted">新版本须保留原知识的标题、类型、适用范围及别名。</p><button class="primary">保存草稿</button></form>');if(existing){['title','kind','jobs','stations','aliases','risk'].forEach(name=>{const input=$('#draft-form [name="'+name+'"]');input.disabled=true})}}
async function doClick(target){const t=target.closest('button');if(!t)return;if(typeof orgClick==='function'&&await orgClick(t))return;if(typeof commerceClick==='function'&&await commerceClick(t))return;if(await operationsClick(t))return;if(await workflowClick(t))return;if(t.dataset.page){page=t.dataset.page;await render();return}if(t.dataset.open){const k=await api('/knowledge/'+t.dataset.open);showModal(cardDetail(k));return}if(t.dataset.ask){await ask(t.dataset.ask);return}if(t.dataset.training){trainingDetail=await api('/training/'+t.dataset.training);const x=trainingDetail;showModal('<h2>'+esc(x.title)+'</h2><p>'+esc(x.objective)+'</p>'+x.materials.map(cardDetail).join('')+'<h2>学习测验</h2><form id="exam" data-id="'+x.id+'">'+x.quiz.map((q,i)=>'<fieldset><legend>'+esc(q.question)+'</legend>'+q.options.map((o,j)=>'<label class="quiz-option"><input type="radio" name="q'+i+'" value="'+j+'" required>'+esc(o)+'</label>').join('')+'</fieldset>').join('')+'<div class="actions"><button class="primary">提交测验</button></div></form>');return}if(t.dataset.feedback){if(t.dataset.feedback==='helpful'){await api('/feedback',{query_id:queryResult.query_id,kind:'helpful',description:''});toast('反馈已记录')}else showModal('<h2>反馈问题</h2><form id="feedback-form" data-kind="'+t.dataset.feedback+'">'+area('请描述遇到的问题','description')+'<div class="actions"><button class="primary">提交反馈</button></div></form>');return}
if(t.dataset.review){const r=revisions.find(r=>r.id===Number(t.dataset.review));showModal('<h2>'+esc(r.title)+' v'+r.version+'</h2><p>'+esc(r.content.summary)+'</p><ol>'+r.content.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'<table class="recipe-table">'+r.content.ingredients.map(i=>'<tr><td>'+esc(i.name)+'</td><td>'+esc(i.amount)+' '+esc(i.unit)+'</td></tr>').join('')+'</table><p>技法：'+esc(r.content.technique)+'　杯型：'+esc(r.content.glass)+'　装饰：'+esc(r.content.garnish)+'</p><p>过敏原：'+esc(r.content.allergens.join('、'))+'</p><div class="source">来源：'+esc(r.source)+'<br>生效：'+date(r.effective_at)+'<br>状态：'+states[r.state]+'</div>');return}
if(t.dataset.editDraft){const r=revisions.find(x=>x.id===Number(t.dataset.editDraft));draftForm({...r,id:r.document_id,revision_id:r.id,jobs:JSON.parse(r.jobs),stations:JSON.parse(r.stations),aliases:JSON.parse(r.aliases)},true);return}
if(t.dataset.diff){const d=await api('/manage/revisions/'+t.dataset.diff+'/diff');const labels={summary:'说明',steps:'步骤',ingredients:'原料',technique:'技法',glass:'杯型',garnish:'装饰',allergens:'过敏原',source:'来源'};const text=v=>Array.isArray(v)?v.map(x=>typeof x==='object'?x.name+' '+x.amount+' '+x.unit:x).join('；'):String(v??'');showModal('<h2>版本差异</h2><p>'+(d.previous_version?'对比上一批准版本 v'+d.previous_version:'首个版本，暂无历史标准')+'</p><div class="diff-list">'+d.changed_fields.map(k=>'<section><h3>'+esc(labels[k]||k)+'</h3><p class="muted">原标准：'+esc(d.before?text(k==='source'?d.before.source:d.before.content[k]):'无')+'</p><p>本版本：'+esc(text(k==='source'?d.after.source:d.after.content[k]))+'</p></section>').join('')+(d.changed_fields.length?'':'<p>正文与来源未变化。</p>')+'</div>');return}
if(t.dataset.editUser){accountForm(accountUsers.find(x=>x.id===Number(t.dataset.editUser)));return}
if(t.dataset.resetPassword){showModal('<h2>重置员工密码</h2><p>旧会话立即失效，员工登录后必须修改密码。请通过私下渠道交付临时密码。</p><form id="reset-password-form" data-id="'+t.dataset.resetPassword+'">'+field('临时密码（至少12位）','temporary_password','','password')+'<button class="primary">确认重置</button></form>');return}
if(t.dataset.newVersion){const r=revisions.find(r=>r.id===Number(t.dataset.newVersion));const items=await api('/knowledge');const k=items.find(k=>k.id===r.document_id);if(!k)throw Error('当前有效版本不在你的岗位或吧台范围内');draftForm({...k,content:r.content,source:r.source});return}
if(t.dataset.submit){await api('/manage/revisions/'+t.dataset.submit+'/submit',{edit_version:revisions.find(r=>r.id===Number(t.dataset.submit)).edit_version});toast('已提交审核');await render();return}
if(t.dataset.publish){showModal('<h2>审核并发布</h2><p>请先查看完整内容，确认来源、适用范围与操作标准。</p><form id="publish-form" data-id="'+t.dataset.publish+'">'+field('生效时间（北京时间）','effective_at','','datetime-local')+field('失效时间（可空）','expires_at','','datetime-local',false)+'<label><input type="checkbox" name="risk_confirmed"> 高风险内容已由负责人确认</label><div class="actions"><button class="primary">确认发布</button></div></form>');return}
if(t.dataset.retire){showModal('<h2>停用知识版本</h2><p>停用后员工将无法再查询此标准；不会自动恢复旧版本。</p><button class="primary" data-confirm-retire="'+t.dataset.retire+'">确认停用</button>');return}if(t.dataset.confirmRetire){await api('/manage/revisions/'+t.dataset.confirmRetire+'/retire',{});closeModal();await render();return}
if(t.dataset.resolve){showModal('<h2>处理反馈</h2><form id="resolve-form" data-id="'+t.dataset.resolve+'">'+area('处理结果和后续行动','resolution')+'<button class="primary">保存处理记录</button></form>');return}
if(t.dataset.practical){showModal('<h2>确认实际操作验收</h2><p>请在现场观察实际操作后记录结果。理论测验必须先通过。</p><form id="practical-form" data-id="'+t.dataset.practical+'">'+area('验收内容与结果（至少5字）','note')+'<button class="primary">确认验收通过</button></form>');return}
if(t.dataset.deactivate){showModal('<h2>停用员工账号</h2><p>该员工的全部会话将失效，培训和审计记录保留。</p><button class="primary" data-confirm-deactivate="'+t.dataset.deactivate+'">确认停用</button>');return}if(t.dataset.confirmDeactivate){await api('/admin/users/'+t.dataset.confirmDeactivate+'/deactivate',{});closeModal();await render();return}
if(t.dataset.filterKind){document.querySelectorAll('[data-filter-kind]').forEach(b=>b.classList.toggle('active',b===t));filterKnowledge();return}
switch(t.dataset.action){case 'logout':await api('/logout',{});user=null;csrf='';activeStore='';renderLogin();break;case 'retry':await render();break;case 'draft':draftForm();break;case 'module':{const items=await api('/knowledge');showModal('<h2>创建学习模块</h2><form id="module-form">'+field('模块标题','title')+area('学习目标','objective')+'<label>学习资料（可多选）</label><select name="revision_ids" multiple required size="5">'+items.map(k=>'<option value="'+k.revision_id+'">'+esc(k.title)+' v'+k.version+'</option>').join('')+'</select>'+field('通过分数','pass_score','100','number')+field('测验题目','question')+area('选项（每行一个，至少两个）','options')+field('正确选项序号（从1开始）','answer','1','number')+'<p class="small muted">此页面创建一道测验题；多个学习要点可拆为独立模块。</p><button class="primary">创建模块</button></form>');break}case 'account':accountForm();break}}
const split=s=>String(s||'').split(/[,，]/).map(s=>s.trim()).filter(Boolean);
const lines=s=>String(s||'').split('\n').map(s=>s.trim()).filter(Boolean);
async function doSubmit(form){const f=new FormData(form),v=Object.fromEntries(f);if(typeof orgSubmit==='function'&&await orgSubmit(form,v,f))return;if(typeof commerceSubmit==='function'&&await commerceSubmit(form,v,f))return;if(await operationsSubmit(form,v,f))return;if(await workflowSubmit(form,v))return;switch(form.id){case 'login':{const data=await api('/login',v);user=data.user;scopeOptions=[];csrf=data.csrf;station=user.stations[0];page='home';await render();break}case 'ask':await ask(v.question);break;case 'feedback-form':await api('/feedback',{query_id:queryResult.query_id,kind:form.dataset.kind,description:v.description});closeModal();toast('反馈已提交主管');break;case 'draft-form':{const ingredients=v.ingredients.trim()==='无'?[]:lines(v.ingredients).map(line=>{const a=line.split('|').map(s=>s.trim());if(a.length!==3)throw Error('原料格式应为：名称 | 数量 | 单位');return {name:a[0],amount:a[1],unit:a[2]}});const payload={document_id:form.dataset.document?Number(form.dataset.document):null,title:v.title,kind:v.kind,jobs:split(v.jobs),stations:split(v.stations),aliases:split(v.aliases),risk:f.has('risk'),source:v.source,change_reason:v.change_reason||'',content:{summary:v.summary,steps:lines(v.steps),ingredients,technique:v.technique,glass:v.glass,garnish:v.garnish,allergens:split(v.allergens)}};if(form.dataset.edit){await api('/manage/revisions/'+form.dataset.edit+'/edit',{content:payload.content,source:payload.source,change_reason:payload.change_reason,edit_version:Number(form.dataset.editVersion)})}else{if(form.dataset.document){const r=revisions.find(x=>x.document_id===Number(form.dataset.document));Object.assign(payload,{title:r.title,kind:r.kind,jobs:JSON.parse(r.jobs),stations:JSON.parse(r.stations),aliases:JSON.parse(r.aliases),risk:Boolean(r.risk)})}await api(form.dataset.proposal?'/manage/proposals/'+form.dataset.proposal+'/draft':'/manage/drafts',payload)}closeModal();toast('草稿已保存');await render();break}case 'publish-form':{const toUTC=s=>new Date(s+':00+08:00').toISOString();await api('/manage/revisions/'+form.dataset.id+'/publish',{effective_at:toUTC(v.effective_at),expires_at:v.expires_at?toUTC(v.expires_at):null,risk_confirmed:f.has('risk_confirmed')});closeModal();toast('知识已发布');await render();break}case 'resolve-form':await api('/manage/feedback/'+form.dataset.id+'/resolve',v);closeModal();await render();break;case 'assign':await api('/manage/assignments',{module_id:Number(v.module_id),user_id:Number(v.user_id)});toast('学习任务已分配');await render();break;case 'module-form':await api('/manage/modules',{title:v.title,objective:v.objective,revision_ids:f.getAll('revision_ids').map(Number),pass_score:Number(v.pass_score),quiz:[{question:v.question,options:lines(v.options),answer:Number(v.answer)-1}]});closeModal();toast('学习模块已创建');await render();break;case 'exam':{const data=await api('/training/'+form.dataset.id+'/submit',{answers:trainingDetail.quiz.map((_,i)=>Number(v['q'+i]))});closeModal();toast('本次得分 '+data.score+'。'+data.message);await render();break}case 'practical-form':await api('/manage/training/'+form.dataset.id+'/practical',v);closeModal();toast('实操验收已记录');await render();break;case 'password-form':await api('/password',v);user=null;csrf='';closeModal();renderLogin();toast('密码已修改，请重新登录');break;case 'scope-form':await api('/admin/scope-options',v);toast('配置已保存');await render();break;case 'reset-password-form':await api('/admin/users/'+form.dataset.id+'/reset-password',v);closeModal();toast('临时密码已设置，员工需要重新登录并改密');await render();break;case 'account-form':await api(form.dataset.id?'/admin/users/'+form.dataset.id+'/edit':'/admin/users',{...v,stations:split(v.stations)});closeModal();toast(form.dataset.id?'账号已更新，旧会话已失效':'账号已创建，首次登录须修改密码');await render();break}}
function filterKnowledge(){const term=($('#filter')?.value||'').toLowerCase();const kind=document.querySelector('[data-filter-kind].active')?.dataset.filterKind||'all';$('#knowledge-list').innerHTML=cards(knowledge.filter(k=>(kind==='all'||kind===k.kind)&&[k.title,...k.aliases].some(s=>s.toLowerCase().includes(term))))}
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button||!Object.keys(button.dataset).length)return;if(busy)return;busy=true;try{await doClick(e.target)}catch(e){toast(e.message)}finally{busy=false}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const button=e.target.querySelector('button');if(button)button.disabled=true;try{await doSubmit(e.target)}catch(err){if(e.target.id==='login')$('#login-error').textContent=err.message;else toast(err.message)}finally{busy=false;if(button)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='filter')filterKnowledge()});
document.addEventListener('change',async e=>{if(e.target.id==='store-switch'){if(busy)return;busy=true;try{activeStore=e.target.value;const current=await api('/me');user=current.user;station=user.stations[0];page='home';closeModal();await render()}catch(err){activeStore='';toast(err.message);const current=await api('/me');user=current.user;station=user.stations[0];await render()}finally{busy=false}return}if(e.target.id==='station'){if(busy){e.target.value=station;return}busy=true;try{station=e.target.value;await render()}catch(err){toast(err.message)}finally{busy=false}}});
$('#close-modal').addEventListener('click',closeModal);
(async()=>{try{const data=await api('/me');user=data.user;csrf=data.csrf;station=user.stations[0];await render()}catch{renderLogin()}})();

function passwordForm(){return '<form id="password-form">'+field('当前密码／临时密码','current_password','','password')+field('新密码（至少12位）','new_password','','password')+'<div class="actions"><button class="primary">保存新密码并重新登录</button><button type="button" data-action="logout">退出登录</button></div></form>'}
function accountForm(existing){const u=existing||{};showModal('<h2>'+(existing?'调整岗位与权限':'新增员工账号')+'</h2><form id="account-form" data-id="'+(u.id||'')+'"><div class="field-grid">'+(existing?'':field('账号（英文、数字、下划线）','username'))+field('姓名','name',u.name||'')+(existing?'':field('初始密码（至少12位，首次登录须修改）','password','','password'))+'<div><label>岗位</label><select name="job">'+scopeOptions.filter(o=>o.kind==='job').map(o=>'<option value="'+esc(o.code)+'" '+(o.code===(u.job||user.job)?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></div>'+field('授权吧台标识（逗号分隔）','stations',(u.stations||[station]).join(','))+'<div><label>系统角色</label><select name="role">'+Object.entries({staff:'员工',manager:'主管',admin:'管理员'}).map(([v,l])=>'<option value="'+v+'" '+(v===(u.role||'staff')?'selected':'')+'>'+l+'</option>').join('')+'</select></div></div><p class="small muted">可用吧台：'+scopeOptions.filter(o=>o.kind==='station').map(o=>esc(o.label)+'（'+esc(o.code)+'）').join('、')+'</p><button class="primary">保存账号</button></form>')}


// Knowledge maintenance and employee requests share the existing role/CSRF boundary.
let memoryItems=[],proposalItems=[],memoryUsers=[];
const proposalStates={open:'待评估',draft_created:'草稿已生成，待审核生效',rejected:'已驳回',closed:'已完成'};
const eventNames={metadata_changed:'调整负责人／复审计划',reviewed:'完成复审',draft_created:'创建草稿',draft_edited:'编辑草稿',submitted:'提交审核',published:'审核发布',retired:'停用版本',proposal_created:'创建提案',proposal_drafted:'提案生成草稿',proposal_rejected:'驳回提案',proposal_closed:'确认提案完成'};
const localTime=s=>s?new Date(new Date(s).getTime()+8*3600000).toISOString().slice(0,16):'';
const utcTime=s=>s?new Date(s+':00+08:00').toISOString():null;
async function renderMemory(content){
  const [data,users]=await Promise.all([api('/manage/memory'),api('/manage/users')]);
  memoryItems=data.items;memoryUsers=users.filter(u=>['manager','admin'].includes(u.role));
  content.innerHTML=heading('知识维护','给每项标准明确负责人和复审时间，保留每次变更的来由。')+
    '<div class="metrics">'+[['知识系列',data.health.total],['缺少有效负责人',data.health.unowned],['复审已到期',data.health.overdue],['无有效版本',data.health.no_current_version]].map(([label,n])=>'<div class="metric"><span class="muted small">'+label+'</span><strong>'+n+'</strong></div>').join('')+'</div><div class="panel">'+
    (memoryItems.length?memoryItems.map(x=>'<div class="list-row"><div><h3>'+esc(x.title)+'</h3><span class="tag">'+(x.current_version?'有效 v'+x.current_version:'暂无有效版本')+'</span>'+(x.overdue?' <span class="tag attention">待复审</span>':'')+'<p class="small muted">负责人：'+esc(x.unowned?'待指定':x.owner_name)+' · 下次复审：'+date(x.review_due_at)+'</p><p class="small muted">最近复审：'+date(x.last_reviewed_at)+'</p></div><div class="actions"><button data-metadata="'+x.id+'">负责人及计划</button><button data-memory-review="'+x.id+'" '+(!x.current_revision_id||x.unowned?'disabled':'')+'>记录复审</button><button data-history="'+x.id+'">变更历史</button><button data-propose-document="'+x.id+'">提出修改</button></div></div>').join(''):'<div class="empty">添加知识后，在这里设置负责人。</div>')+'</div>';
}
async function renderProposals(content){
  proposalItems=await api('/manage/proposals');
  content.innerHTML=heading('知识提案','反馈 → 提案 → 人工核对草稿 → 审核发布 → 生效后确认完成。','<button class="primary" data-action="proposal">新增提案</button>')+'<div class="panel">'+
    (proposalItems.length?proposalItems.map(p=>'<div class="list-row"><div><h3>提案 #'+p.id+' · '+esc(p.title||'新增知识缺口')+'</h3><span class="tag">'+proposalStates[p.state]+'</span><p class="note">'+esc(p.description)+'</p>'+(p.question?'<p class="small muted">原始问题：'+esc(p.question)+' · 反馈 #'+p.feedback_id+'</p>':'')+(p.revision_id?'<p class="small muted">关联草稿编号：'+p.revision_id+'，请前往知识管理审核。</p>':'')+(p.decision_note?'<p>处理记录：'+esc(p.decision_note)+'</p>':'')+'</div><div class="actions">'+(p.state==='open'?'<button data-proposal-draft="'+p.id+'">填写提案草稿</button><button data-decision="'+p.id+'" data-decision-action="reject">驳回</button>':p.state==='draft_created'?'<button data-page="manage">打开知识管理</button><button data-decision="'+p.id+'" data-decision-action="close">确认生效并完成</button>':'')+'</div></div>').join(''):'<div class="empty">暂无提案。可从反馈中心把问题转成修改建议。</div>')+'</div>';
}
async function renderRequests(content){
  const items=await api('/my-requests');
  content.innerHTML=heading('我的求助','查询后点击“请主管确认”，在这里查看处理进度。')+'<div class="panel">'+(items.length?items.map(x=>'<div class="list-row"><div><h3>'+esc(x.question)+'</h3><span class="tag">'+(x.state==='closed'?'主管已处理':'待主管处理')+'</span><p class="small muted">求助 #'+x.feedback_id+' · '+date(x.created_at)+'</p>'+(x.resolution?'<p class="note">主管回复：'+esc(x.resolution)+'</p>':'<p class="muted small">涉及安全或紧急情况，请直接联系现场主管。</p>')+'</div><button data-request-ask="'+esc(x.question)+'">按最新标准重查</button></div>').join(''):'<div class="empty">你还没有提交求助。</div>')+'</div>';
}
function answerEvidence(result){
  return '<p class="small muted">'+({answered:'已找到证据',needs_clarification:'需要你选择标准',needs_supervisor:'需要主管确认',no_evidence:'缺少已审核依据'}[result.status]||'')+'</p>'+
    (result.citations||[]).map(c=>'<section class="evidence"><h3>标准原文摘录</h3><p class="note">'+esc(c.text)+'</p><p class="small muted">'+esc(c.title)+' · v'+c.version+' · '+esc(c.source)+'</p><button data-citation="'+c.revision_id+'">核验引用并查看全文</button></section>').join('')+
    (result.supervisors?.length?'<p class="small muted">可联系主管：'+esc(result.supervisors.map(s=>s.name).join('、'))+'（请现场联系；提交求助会进入反馈中心）</p>':'');
}
async function proposalForm(feedbackId=null,documentId=null){
  const [memory,revs]=await Promise.all([api('/manage/memory'),api('/manage/revisions')]);
  let items=memory.items,description='';
  if(feedbackId){const feedbacks=await api('/manage/feedback');const f=feedbacks.find(x=>x.id===Number(feedbackId));if(!f)throw Error('反馈不存在');description=f.description||f.question;const ids=JSON.parse(f.revision_ids);items=items.filter(d=>revs.some(r=>r.document_id===d.id&&ids.includes(r.id)));}
  showModal('<h2>创建知识提案</h2><p>提案仅记录修改建议。草稿仍需人工核对、审核发布。</p><form id="proposal-form" data-feedback="'+(feedbackId||'')+'"><label for="proposal-document">关联知识</label><select id="proposal-document" name="document_id"><option value="">新增知识缺口（不关联旧标准）</option>'+items.map(d=>'<option value="'+d.id+'" '+(d.id===Number(documentId)?'selected':'')+'>'+esc(d.title)+'</option>').join('')+'</select>'+area('建议内容及原因','description',description)+'<button class="primary">保存提案</button></form>');
}
async function workflowClick(t){
  if(t.dataset.metadata){const x=memoryItems.find(x=>x.id===Number(t.dataset.metadata));showModal('<h2>负责人及复审计划</h2><p>'+esc(x.title)+'</p><form id="metadata-form" data-id="'+x.id+'" data-version="'+x.metadata_version+'"><label for="owner">知识负责人</label><select id="owner" name="owner_id"><option value="">暂未指定</option>'+memoryUsers.map(u=>'<option value="'+u.id+'" '+(u.id===x.owner_id?'selected':'')+'>'+esc(u.name)+'</option>').join('')+'</select>'+field('下次复审（北京时间，可空）','review_due_at',localTime(x.review_due_at),'datetime-local',false)+'<button class="primary">保存负责人及计划</button></form>');return true;}
  if(t.dataset.memoryReview){const x=memoryItems.find(x=>x.id===Number(t.dataset.memoryReview));const k=await api('/citations/'+x.current_revision_id);showModal(cardDetail(k)+'<h2>确认复审结果</h2><p>请核对当前全文；需要修改时先创建提案，不要用复审代替改版。</p><form id="memory-review-form" data-id="'+x.id+'" data-revision="'+k.revision_id+'">'+area('本次核对结论','note')+field('下次复审（北京时间）','next_review_at','','datetime-local')+'<button class="primary">确认当前标准仍适用</button></form>');return true;}
  if(t.dataset.history){const h=await api('/manage/memory/'+t.dataset.history+'/history');showModal('<h2>变更历史</h2><p class="muted small">'+esc(h.note)+'</p><h3>历史版本</h3>'+h.revisions.map(r=>'<div class="history-entry"><strong>v'+r.version+' · '+states[r.state]+'</strong><p>变更原因：'+esc(r.change_reason||'旧版本未记录')+'</p><p class="small muted">'+esc(r.source)+' · 生效：'+date(r.effective_at)+'</p></div>').join('')+'<h3>操作记录</h3>'+h.events.map(e=>'<div class="history-entry"><strong>'+esc(eventNames[e.kind]||e.kind)+'</strong><p class="small muted">'+esc(e.actor_name)+' · '+date(e.created_at)+'</p>'+(e.payload.note||e.payload.reason||e.payload.description?'<p>'+esc(e.payload.note||e.payload.reason||e.payload.description)+'</p>':'')+'</div>').join(''));return true;}
  if(t.dataset.proposeDocument||t.dataset.proposeFeedback||t.dataset.action==='proposal'){await proposalForm(t.dataset.proposeFeedback||null,t.dataset.proposeDocument||null);return true;}
  if(t.dataset.proposalDraft){const p=proposalItems.find(p=>p.id===Number(t.dataset.proposalDraft));let k;if(p.document_id){revisions=await api('/manage/revisions');const r=revisions.filter(r=>r.document_id===p.document_id).sort((a,b)=>b.version-a.version)[0];if(!r)throw Error('原知识不存在');k={...r,id:r.document_id,jobs:JSON.parse(r.jobs),stations:JSON.parse(r.stations),aliases:JSON.parse(r.aliases),change_reason:p.description};}draftForm(k,false,p.id);return true;}
  if(t.dataset.decision){showModal('<h2>'+(t.dataset.decisionAction==='reject'?'驳回提案':'确认提案已完成')+'</h2><p>完成操作会核对关联版本是否正式生效，并关闭原反馈。</p><form id="decision-form" data-id="'+t.dataset.decision+'" data-action="'+t.dataset.decisionAction+'">'+area('处理说明','note')+'<button class="primary">确认处理</button></form>');return true;}
  if(t.dataset.citation){const k=await api('/citations/'+t.dataset.citation);showModal(cardDetail(k));return true;}
  if(t.dataset.escalate){showModal('<h2>请主管确认</h2><p>提交后主管可在反馈中心处理。需要立即协助时，请现场联系主管。</p><form id="escalate-form" data-id="'+t.dataset.escalate+'">'+area('补充现场情况','note')+'<button class="primary">提交求助</button></form>');return true;}
  if(t.dataset.requestAsk){page='home';await render();await ask(t.dataset.requestAsk);return true;}
  return false;
}
async function workflowSubmit(form,v){
  switch(form.id){
    case 'metadata-form':await api('/manage/memory/'+form.dataset.id+'/metadata',{owner_id:v.owner_id?Number(v.owner_id):null,review_due_at:utcTime(v.review_due_at),metadata_version:Number(form.dataset.version)});break;
    case 'memory-review-form':await api('/manage/memory/'+form.dataset.id+'/review',{revision_id:Number(form.dataset.revision),next_review_at:utcTime(v.next_review_at),note:v.note});break;
    case 'proposal-form':await api('/manage/proposals',{feedback_id:form.dataset.feedback?Number(form.dataset.feedback):null,document_id:v.document_id?Number(v.document_id):null,description:v.description});page='proposals';break;
    case 'decision-form':await api('/manage/proposals/'+form.dataset.id+'/decision',{action:form.dataset.action,note:v.note});break;
    case 'escalate-form':{const r=await api('/queries/'+form.dataset.id+'/escalate',{note:v.note});closeModal();toast(r.existing?'该问题已提交求助，可在“我的求助”查看':'求助已提交，可在“我的求助”查看');return true;}
    default:return false;
  }
  closeModal();toast('记录已保存');await render();return true;
}


